ee:message.ee:set-payload:
%dw 2.0
output application/json
var raw = vars.parameters.FILTERS
var lista = raw splitBy ";"
var pares = lista map (item) -> item splitBy ":"
var filtrados = pares filter (kv) -> sizeOf(kv) == 2
var resultado = filtrados reduce (pair, acc = {}) -> acc ++ {
  (pair[0] as String {lowerFirst: true}): pair[1]
}
---
{
  filtros: resultado
}

%dw 2.0
output application/json

// 1. Diccionario
var configMap = (vars.approvals default []) reduce (item, acc = {}) -> 
    acc ++ { (item.parametro): item }

// 2. Filtros Validados
var filtrosValidos = (payload.filtros mapObject (v, k) -> {
    (k): {
        valor: v,
        config: configMap[k as String]
    }
}) filterObject ($.config != null)

// 3. Agrupación
var filtrosAgrupados = filtrosValidos groupBy ($.config.contenedor)

---
{
    "query": (
        // Bloque ROOT
        (if (filtrosAgrupados.root != null) 
            filtrosAgrupados.root mapObject (v, k) -> {
                (v.config.valor): if (v.config.tipoDato == "number") v.valor as Number
                                 else if (v.config.usaRegex == true) { "\$regex": v.valor, "\$options": "i" }
                                 else v.valor
            } 
        else {})
        ++ 
        // Bloque BUNDLE
        ((filtrosAgrupados -- ["root"]) mapObject (filtros, nombreContenedor) -> {
            (nombreContenedor): {
                "\$all": filtros pluck (v) -> {
                    "\$elemMatch": {
                        "parametro": v.config.valor,
                        "valor": if (v.config.tipoDato == "number") v.valor as Number
                                 else if (v.config.usaRegex == true) { "\$regex": v.valor, "\$options": "i" }
                                 else v.valor
                    }
                }
            }
        })
    ),
    "limit": (vars.parameters.LIMIT default 10) as Number,
    "offset": (vars.parameters.OFFSET default 0) as Number
}
